export function hindiTopicsForDay(day) {
  return day.hindi[0] === "mixed" ? Object.values(hindiTopicIDs) : [hindiTopicIDs[day.hindi[0]]];
}

export function topicIDsForDay(day) {
  if (foundationDays[day.day]) return foundationDays[day.day];
  const subjectIDs = Object.entries(subjects).filter(([,value]) => value[2].some(group => day.groups.includes(group))).map(([id]) => id);
  return topics.filter(topic => subjectIDs.includes(topic.subject)).map(topic => topic.id);
}
export function daysForTopic(topic) {
  return days.filter(day => topicIDsForDay(day).concat(hindiTopicsForDay(day)).includes(topic.id));
}

